// Station 5: Mehrere Perzeptronen stecken einen Raum ab.
// 729 Probepunkte im Würfel: grün = das Netz sagt 1 (innen), grau = 0 (außen).
// Ziel (Aufgabe 5): eine Kugel um die Mitte (0,5 | 0,5 | 0,5) mit Radius 0,35 möglichst gut nachbauen.
// Lösung
Raum3d raum = new Raum3d();
Netz netz = Netz.quader(0.2, 0.8, 0.2, 0.8, 0.2, 0.8);
// Aufgabe 5: Netz.quader(0.25, 0.75, …), Netz.oktaeder(0.5), Netz.beide(Netz.quader(…), Netz.oktaeder(…))

int innen = 0;
int abweichungen = 0;
for (int i = 1; i <= 9; i++) {
   for (int j = 1; j <= 9; j++) {
      for (int k = 1; k <= 9; k++) {
         double[] p = {i / 10.0, j / 10.0, k / 10.0};
         boolean drin = netz.vorwaerts(p) == 1;
         raum.probe(p[0], p[1], p[2], drin);
         double d2 = (p[0] - 0.5) * (p[0] - 0.5) + (p[1] - 0.5) * (p[1] - 0.5) + (p[2] - 0.5) * (p[2] - 0.5);
         boolean kugel = d2 <= 0.35 * 0.35 + 0.000001;
         if (drin) {
            innen++;
         }
         if (drin != kugel) {
            abweichungen++;
         }
      }
   }
}
println("Neuronen in der verdeckten Schicht: " + netz.getAnzahlVerdeckt());
println("Punkte innen: " + innen + " von 729 (in der Kugel: 179)");
println("Abweichungen von der Kugel: " + abweichungen);

/**
 * Ein Netz aus Perzeptronen (Station 5): eine verdeckte Schicht aus Grenz-Neuronen und ein Ausgabeneuron.
 * Eingabeschicht: der Punkt x = (x1 | x2 | x3). Verdeckte Schicht: jedes Perzeptron sagt, auf welcher Seite
 * seiner Ebene der Punkt liegt (1 oder 0). Ausgabeschicht: ein Perzeptron kombiniert diese Antworten.
 */
public class Netz {
   private Perzeptron[] verdeckt;
   private Perzeptron ausgabe;

   public Netz(Perzeptron[] verdeckt, Perzeptron ausgabe) {
      this.verdeckt = verdeckt;
      this.ausgabe = ausgabe;
   }

   // TODO 4a: Forward Propagation: ① jede verdeckte Ausgabe h[i] berechnen, ② daraus die Ausgabe des Netzes
   public int vorwaerts(double[] x) {
      double[] h = new double[verdeckt.length];
      for (int i = 0; i < verdeckt.length; i++) {
         h[i] = verdeckt[i].ausgabe(x);           // ①
      }
      return ausgabe.ausgabe(h);                  // ②
   }

   // Ein Grenz-Neuron mit den Gewichten w0 + w1 · x1 + w2 · x2 + w3 · x3 (fertig)
   public static Perzeptron neuron(double w0, double w1, double w2, double w3) {
      Perzeptron p = new Perzeptron(3, 0.1);
      double[] w = {w0, w1, w2, w3};
      p.setGewichte(w);
      return p;
   }

   // TODO 4b: UND-Neuron für n Eingaben (0 oder 1): Ausgabe 1 nur, wenn alle n Eingaben 1 sind
   public static Perzeptron und(int n) {
      Perzeptron p = new Perzeptron(n, 0.1);
      double[] w = new double[n + 1];
      w[0] = -(n - 0.5);
      for (int i = 1; i <= n; i++) {
         w[i] = 1;
      }
      p.setGewichte(w);
      return p;
   }

   // TODO 4c: Quader xMin <= x1 <= xMax, yMin <= x2 <= yMax, zMin <= x3 <= zMax aus 6 Grenz-Neuronen und einem UND
   public static Netz quader(double xMin, double xMax, double yMin, double yMax, double zMin, double zMax) {
      Perzeptron[] g = new Perzeptron[6];
      g[0] = neuron(-xMin, 1, 0, 0);     // x1 >= xMin  ⇔  -xMin + x1 >= 0
      g[1] = neuron(xMax, -1, 0, 0);     // x1 <= xMax  ⇔  xMax - x1 >= 0
      g[2] = neuron(-yMin, 0, 1, 0);
      g[3] = neuron(yMax, 0, -1, 0);
      g[4] = neuron(-zMin, 0, 0, 1);
      g[5] = neuron(zMax, 0, 0, -1);
      return new Netz(g, und(6));
   }

   // TODO 4d: Oktaeder |x1 - 0,5| + |x2 - 0,5| + |x3 - 0,5| <= r aus 8 Grenz-Neuronen (alle Vorzeichen) und einem UND
   //          Grenz-Neuron für die Vorzeichen (a | b | c): a·(x1 - 0,5) + b·(x2 - 0,5) + c·(x3 - 0,5) <= r
   public static Netz oktaeder(double r) {
      Perzeptron[] g = new Perzeptron[8];
      int n = 0;
      for (int a = -1; a <= 1; a = a + 2) {
         for (int b = -1; b <= 1; b = b + 2) {
            for (int c = -1; c <= 1; c = c + 2) {
               g[n] = neuron(r + 0.5 * (a + b + c), -a, -b, -c);
               n++;
            }
         }
      }
      return new Netz(g, und(8));
   }

   // Zwei Netze mit UND verbinden: alle Grenz-Neuronen beider Netze in eine verdeckte Schicht (fertig)
   public static Netz beide(Netz eins, Netz zwei) {
      int n = eins.verdeckt.length + zwei.verdeckt.length;
      Perzeptron[] g = new Perzeptron[n];
      for (int i = 0; i < eins.verdeckt.length; i++) {
         g[i] = eins.verdeckt[i];
      }
      for (int i = 0; i < zwei.verdeckt.length; i++) {
         g[eins.verdeckt.length + i] = zwei.verdeckt[i];
      }
      return new Netz(g, und(n));
   }

   public int getAnzahlVerdeckt() {
      return verdeckt.length;
   }
}

/**
 * Ein Perzeptron (fertig aus Station 4), Schreibweise wie in Klasse 11:
 * Nettoeingabe z = w0 · 1 + w1 · x1 + w2 · x2 + … , Ausgabe 1, wenn z >= 0, sonst 0.
 * gewichte[0] ist w0 (Bias), gewichte[1] ist w1 für das erste Merkmal x[0], usw.
 * Muss nicht verändert werden.
 */
public class Perzeptron {
   private double[] gewichte;
   private double lernrate;

   public Perzeptron(int anzahlEingaben, double lernrate) {
      gewichte = new double[anzahlEingaben + 1];
      this.lernrate = lernrate;
   }

   public double[] getGewichte() {
      return gewichte;
   }

   public void setGewichte(double[] neu) {
      for (int i = 0; i < gewichte.length; i++) {
         gewichte[i] = neu[i];
      }
   }

   // Nettoeingabe z = w0 · 1 + w1 · x[0] + w2 · x[1] + …
   public double netto(double[] x) {
      double z = gewichte[0];
      for (int i = 0; i < x.length; i++) {
         z = z + gewichte[i + 1] * x[i];
      }
      return z;
   }

   // Aktivierungsfunktion (Stufe): 1, wenn z >= 0, sonst 0
   public int aktivierung(double z) {
      if (z >= 0) {
         return 1;
      }
      return 0;
   }

   // Ausgabe des Perzeptrons für die Eingabe x
   public int ausgabe(double[] x) {
      return aktivierung(netto(x));
   }

   // Delta-Lernregel für ein Beispiel: Δwi = lernrate · (ziel − ausgabe) · xi  (mit x0 = 1)
   //          Rückgabe: true, wenn die Gewichte geändert wurden (das Beispiel war falsch eingeordnet)
   public boolean lerne(double[] x, int ziel) {
      int fehler = ziel - ausgabe(x);
      if (fehler == 0) {
         return false;
      }
      gewichte[0] = gewichte[0] + lernrate * fehler;
      for (int i = 0; i < x.length; i++) {
         gewichte[i + 1] = gewichte[i + 1] + lernrate * fehler * x[i];
      }
      return true;
   }

   // Eine Epoche: jedes Beispiel einmal der Reihe nach lernen (fertig). Ziel 1 für artEins, sonst 0.
   // Rückgabe: Zahl der Korrekturen in dieser Epoche
   public int epoche(Punkt[] daten, String artEins) {
      int korrekturen = 0;
      for (int i = 0; i < daten.length; i++) {
         int ziel = 0;
         if (daten[i].getArt().equals(artEins)) {
            ziel = 1;
         }
         if (lerne(daten[i].getWerte(), ziel)) {
            korrekturen++;
         }
      }
      return korrekturen;
   }
}

/**
 * Ein Datenpunkt im Merkmalsraum: seine Merkmalswerte (normiert auf 0 bis 1),
 * die wahre Art (nur zum Vergleichen, k-Means kennt sie nicht!) und die Nummer seines Clusters.
 * Muss nicht verändert werden.
 */
public class Punkt {
   private double[] werte;
   private String art;
   private int cluster;

   public Punkt(double[] werte, String art) {
      this.werte = werte;
      this.art = art;
      cluster = -1;            // -1: noch keinem Cluster zugeordnet
   }

   public double[] getWerte() {
      return werte;
   }

   public double getWert(int i) {
      return werte[i];
   }

   public int getAnzahlMerkmale() {
      return werte.length;
   }

   public String getArt() {
      return art;
   }

   public int getCluster() {
      return cluster;
   }

   public void setCluster(int cluster) {
      this.cluster = cluster;
   }
}

/**
 * Zeichnet Pinguine, eine Entscheidungsebene und Probepunkte in einem drehbaren 3D-Würfel (Kantenlänge 10).
 * Achsen: x (rot) = Schnabellänge, y (grün) = Schnabeltiefe, z (blau) = Flossenlänge, jeweils normiert (0 bis 1).
 * Farben: Esels petrol, Adélie orange, Zügel violett; falsch eingeordnete Pinguine schwarz.
 * Drehen: im Grafikfenster mit der Maus ziehen, zoomen: Mausrad. Muss nicht verändert werden.
 */
public class Raum3d {
   private World3d welt;
   private Sphere3d[] kugeln;
   private Plane3d ebene;
   private double s = 10;

   public Raum3d() {
      welt = new World3d();
      welt.setBackgroundColor(0xf8fafc);
      Box3d rahmen = new Box3d(s, s, s);
      rahmen.setMaterial(new BasicMaterial3d(0x94a3b8, true));
      rahmen.moveTo(s / 2, s / 2, s / 2);
      welt.getCamera().moveTo(s * 1.55, s * 1.15, s * 1.75);
      welt.getCamera().lookAt(s / 2, s / 2, s / 2, new Vector3(0, 1, 0), true);
      kugeln = new Sphere3d[0];
   }

   private int artFarbe(String art) {
      if (art.equals("Adelie")) {
         return 0xea580c;
      }
      if (art.equals("Zuegel")) {
         return 0x9333ea;
      }
      return 0x0e7490;
   }

   // Zeigt alle Pinguine als Kugeln in der Farbe ihrer Art.
   public void zeige(Punkt[] punkte) {
      kugeln = new Sphere3d[punkte.length];
      for (int i = 0; i < punkte.length; i++) {
         Sphere3d kugel = new Sphere3d(0.13, 8, 6);
         kugel.setMaterial(new LambertMaterial3d(artFarbe(punkte[i].getArt())));
         kugel.moveTo(s * punkte[i].getWert(0), s * punkte[i].getWert(1), s * punkte[i].getWert(2));
         kugeln[i] = kugel;
      }
   }

   // Färbt falsch eingeordnete Pinguine schwarz (Ziel 1 = artEins), alle anderen in ihrer Art.
   public void markiere(Punkt[] punkte, Perzeptron p, String artEins) {
      for (int i = 0; i < punkte.length; i++) {
         int ziel = 0;
         if (punkte[i].getArt().equals(artEins)) {
            ziel = 1;
         }
         if (p.ausgabe(punkte[i].getWerte()) != ziel) {
            kugeln[i].getMaterial().setColor(0x0f172a);
         } else {
            kugeln[i].getMaterial().setColor(artFarbe(punkte[i].getArt()));
         }
      }
   }

   // Zeigt die Ebene w0 + w1 · x1 + w2 · x2 + w3 · x3 = 0 (w = Gewichte des Perzeptrons, w[0] = Bias).
   public void zeigeEbene(double[] w) {
      if (ebene == null) {
         ebene = new Plane3d(16, 16);
         BasicMaterial3d m = new BasicMaterial3d(0xd97706, false);
         m.setAlpha(0.35);
         m.setTransparent(true);
         ebene.setMaterial(m);
         ebene.enableFrontBackSide(true, true);
      }
      double n2 = w[1] * w[1] + w[2] * w[2] + w[3] * w[3];
      if (n2 < 0.000001) {
         ebene.setVisible(false);
         return;
      }
      ebene.setVisible(true);
      // Punkt der Ebene, der der Würfelmitte (0,5 | 0,5 | 0,5) am nächsten liegt
      double t = (w[0] + 0.5 * (w[1] + w[2] + w[3])) / n2;
      double px = 0.5 - t * w[1];
      double py = 0.5 - t * w[2];
      double pz = 0.5 - t * w[3];
      ebene.moveTo(s * px, s * py, s * pz);
      ebene.lookAt(s * (px + w[1]), s * (py + w[2]), s * (pz + w[3]), new Vector3(0, 1, 0));
   }

   // Ein kleiner Probepunkt (normierte Koordinaten), z. B. für das Abstecken eines Raums in Station 5.
   public void probe(double x, double y, double z, boolean innen) {
      Sphere3d k = new Sphere3d(0.1, 6, 4);
      if (innen) {
         k.setMaterial(new LambertMaterial3d(0x16a34a));
      } else {
         LambertMaterial3d m = new LambertMaterial3d(0xcbd5e1);
         m.setAlpha(0.25);
         m.setTransparent(true);
         k.setMaterial(m);
      }
      k.moveTo(s * x, s * y, s * z);
   }

   public void warte(int millisekunden) {
      SystemTools.pause(millisekunden);
   }

   // Gewichte gerundet als Text, z. B. "(0.12 | -1.3 | 0.4 | 2.0)"
   public static String text(double[] w) {
      String t = "(";
      for (int i = 0; i < w.length; i++) {
         if (i > 0) {
            t = t + " | ";
         }
         t = t + Math.round(w[i] * 1000) / 1000.0;
      }
      return t + ")";
   }
}

/**
 * Tests für Netz. Starten: Klick auf das kleine Dreieck links neben "@Test"
 * oder auf den Knopf "Alle Tests starten" in der Leiste.
 */
public class NetzTest {

   @Test
   public void vorwaertsZweiSchichten() {
      // verdeckt: x1 >= 0,5 und x2 >= 0,5; Ausgabe: beide müssen 1 sagen (w0 = -1,5, Gewichte 1)
      Perzeptron[] g = {Netz.neuron(-0.5, 1, 0, 0), Netz.neuron(-0.5, 0, 1, 0)};
      Perzeptron aus = new Perzeptron(2, 0.1);
      double[] w = {-1.5, 1, 1};
      aus.setGewichte(w);
      Netz netz = new Netz(g, aus);
      double[] a = {0.8, 0.9, 0};
      double[] b = {0.8, 0.1, 0};
      Assertions.assertEquals(1, netz.vorwaerts(a), "TODO 4a: (0,8 | 0,9 | 0) liegt auf der 1-Seite beider Grenzen, das Netz muss 1 liefern.");
      Assertions.assertEquals(0, netz.vorwaerts(b), "TODO 4a: (0,8 | 0,1 | 0) liegt nur auf einer 1-Seite, das Netz muss 0 liefern.");
   }

   @Test
   public void undNeuron() {
      Perzeptron u = Netz.und(3);
      double[] alle = {1, 1, 1};
      double[] zwei = {1, 0, 1};
      double[] keins = {0, 0, 0};
      Assertions.assertEquals(1, u.ausgabe(alle), "TODO 4b: UND mit drei Einsen muss 1 liefern.");
      Assertions.assertEquals(0, u.ausgabe(zwei), "TODO 4b: UND mit (1 | 0 | 1) muss 0 liefern.");
      Assertions.assertEquals(0, u.ausgabe(keins), "TODO 4b: UND mit lauter Nullen muss 0 liefern.");
      Perzeptron u6 = Netz.und(6);
      double[] fuenf = {1, 1, 1, 1, 1, 0};
      Assertions.assertEquals(0, u6.ausgabe(fuenf), "TODO 4b: UND für 6 Eingaben: fünf Einsen reichen nicht.");
   }

   @Test
   public void quaderInnenAussen() {
      Netz q = Netz.quader(0.2, 0.8, 0.3, 0.7, 0.4, 0.6);
      double[] mitte = {0.5, 0.5, 0.5};
      double[] links = {0.1, 0.5, 0.5};
      double[] oben = {0.5, 0.9, 0.5};
      double[] hinten = {0.5, 0.5, 0.65};
      Assertions.assertEquals(1, q.vorwaerts(mitte), "TODO 4c: Die Mitte liegt im Quader.");
      Assertions.assertEquals(0, q.vorwaerts(links), "TODO 4c: x1 = 0,1 ist kleiner als xMin = 0,2.");
      Assertions.assertEquals(0, q.vorwaerts(oben), "TODO 4c: x2 = 0,9 ist größer als yMax = 0,7.");
      Assertions.assertEquals(0, q.vorwaerts(hinten), "TODO 4c: x3 = 0,65 ist größer als zMax = 0,6.");
   }

   @Test
   public void oktaederSelbstGebaut() {
      Netz o = Netz.oktaeder(0.3);
      double[] mitte = {0.5, 0.5, 0.5};
      double[] spitze = {0.75, 0.5, 0.5};
      double[] ecke = {0.7, 0.7, 0.5};
      Assertions.assertEquals(1, o.vorwaerts(mitte), "TODO 4d: Die Mitte liegt im Oktaeder.");
      Assertions.assertEquals(1, o.vorwaerts(spitze), "TODO 4d: (0,75 | 0,5 | 0,5): Summe der Abstände 0,25 <= 0,3, also innen.");
      Assertions.assertEquals(0, o.vorwaerts(ecke), "TODO 4d: (0,7 | 0,7 | 0,5): 0,2 + 0,2 + 0 = 0,4 > 0,3, also außen.");
   }
}
